    public boolean write(YamlConfiguration yaml) {
        if (!writable()) {
            return false;
        }
        try {
            YamlFiles.write(file, yaml);
            return true;
        } catch (IOException exception) {
            logger.log(Level.SEVERE, "Failed to save " + file.getName(), exception);
            return false;
        }
    }

